import { AIChat } from "@/components/ai-chat/ai-chat";

const AIChatPage = () => <AIChat />;

export default AIChatPage;

"use client";

import { EllipsisIcon, Trash2Icon } from "lucide-react";
import React from "react";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";
import { Button } from "@/components/ui/button";
import {
  Context,
  ContextBody,
  ContextContent,
  ContextFooter,
  ContextHeader,
  ContextMeter,
  ContextTrigger,
  ContextUsageRow,
} from "@/components/ui/context";
import {
  Queue,
  QueueItem,
  QueueItemAction,
  QueueItemActions,
  QueueItemContent,
  QueueList,
  QueueSection,
  QueueSectionContent,
  QueueSectionHeader,
} from "@/components/ui/queue";
import {
  SidebarInset,
  SidebarProvider,
  SidebarTrigger,
} from "@/components/ui/sidebar";
import { ChatComposer } from "@/components/ai-chat/chat-composer";
import { ChatProjects } from "@/components/ai-chat/chat-projects";
import {
  ChatSidebar,
  type ChatView,
  type ConversationSummary,
} from "@/components/ai-chat/chat-sidebar";
import { type ChatMessage, ChatThread } from "@/components/ai-chat/chat-thread";

interface Conversation extends ConversationSummary {
  messages: readonly ChatMessage[];
  project?: string;
}

const MODEL_OPTIONS = [
  { group: "Models", label: "GPT-4", value: "gpt-4" },
  { group: "Models", label: "GPT-4.1", value: "gpt-4.1" },
  { group: "Models", label: "GPT-4.1 Mini", value: "gpt-4.1-mini" },
  { group: "Agents", label: "Research", value: "agent-research" },
  { group: "Agents", label: "Coding", value: "agent-coding" },
] as const;

const CONTEXT_USAGE = [
  { title: "Input", value: 4200 },
  { title: "Output", value: 860 },
  { title: "Reasoning", value: 640 },
  { title: "Cache", value: 1200 },
];

const conversations: readonly Conversation[] = [
  {
    group: "Recents",
    id: "launch-plan",
    messages: [
      {
        attachment: {
          description: "PDF · 1.2 MB",
          name: "launch-brief.pdf",
        },
        content:
          "Turn this launch brief into a concise plan for the product team.",
        id: "launch-user",
        role: "user",
      },
      {
        approvalPlan: {
          steps: [
            { id: "1", title: "Confirm audience and release boundary" },
            { id: "2", title: "Assign owners to launch risks" },
            { id: "3", title: "Draft weekly milestone reviews" },
            { id: "4", title: "Publish one-page summary" },
          ],
          summary:
            "Lock scope, assign risk owners, and turn the brief into weekly milestones.",
          title: "Launch plan",
        },
        confirmation: "Allow reading launch-brief.pdf for planning context?",
        content:
          "Start with three decisions: confirm the audience, lock the release boundary, and assign one owner to each launch risk. Then turn the brief into milestones that can be reviewed weekly.",
        id: "launch-assistant",
        plan: {
          tasks: [
            {
              file: "launch-brief.pdf",
              status: "completed",
              title: "Extract decisions from the brief",
            },
            {
              status: "in-progress",
              title: "Draft milestone checklist",
            },
          ],
          title: "Launch readiness",
        },
        reasoning: {
          content:
            "The brief already names the audience and three launch risks. I should convert those into owned decisions and a weekly review cadence instead of inventing new workstreams.",
          duration: 6,
        },
        role: "assistant",
        sources: [
          {
            href: "https://shark-ui.com/docs",
            title: "Shark UI Docs",
          },
          {
            href: "https://ark-ui.com",
            title: "Ark UI",
          },
        ],
        tool: {
          file: "launch-brief.pdf",
          name: "Read",
          pathLabel: "File",
        },
      },
    ],
    project: "Launch planning",
    title: "Launch plan",
  },
  {
    group: "Recents",
    id: "research-notes",
    messages: [
      {
        content:
          "Summarize the strongest themes from last week's research notes.",
        id: "research-user",
        role: "user",
      },
      {
        content:
          "The recurring themes are faster onboarding, clearer ownership, and fewer context switches. Validate them against the original notes before using them as product evidence.",
        id: "research-assistant",
        role: "assistant",
      },
    ],
    project: "Research & Analysis",
    title: "User research analysis",
  },
  {
    group: "Yesterday",
    id: "release-checklist",
    messages: [
      {
        content: "Draft a short release checklist for a frontend change.",
        id: "release-user",
        role: "user",
      },
      {
        content:
          "Check keyboard navigation, responsive layouts, theme variants, loading and empty states, then run lint, type checking, and the production build.",
        id: "release-assistant",
        role: "assistant",
      },
    ],
    project: "Release notes",
    title: "Release checklist",
  },
] as const;

const INITIAL_QUEUE = [
  { id: "q1", title: "Summarize competitor notes" },
  { id: "q2", title: "Draft launch FAQ" },
] as const;

const getConversation = (id: string) =>
  conversations.find((conversation) => conversation.id === id) ?? null;

export const AIChat = () => {
  const nextMessageId = React.useRef(0);
  const [activeView, setActiveView] = React.useState<ChatView>("chat");
  const [activeConversationId, setActiveConversationId] = React.useState<
    string | null
  >(conversations[0]?.id ?? null);
  const [messages, setMessages] = React.useState<readonly ChatMessage[]>(
    conversations[0]?.messages ?? []
  );
  const [thinkMode, setThinkMode] = React.useState(true);
  const [model, setModel] = React.useState(["gpt-4"]);
  const [usedTokens, setUsedTokens] = React.useState(18_420);
  const [queueItems, setQueueItems] = React.useState(() => [...INITIAL_QUEUE]);

  const activeConversation = activeConversationId
    ? getConversation(activeConversationId)
    : null;
  const selectedModel =
    MODEL_OPTIONS.find((option) => model.includes(option.value)) ??
    MODEL_OPTIONS[0];

  const breadcrumbProject =
    activeView === "projects"
      ? "Projects"
      : (activeConversation?.project ?? "Design help");
  const breadcrumbTitle =
    activeView === "projects"
      ? "All projects"
      : (activeConversation?.title ?? "New chat");

  const handleSend = (content: string) => {
    const sequence = nextMessageId.current;
    nextMessageId.current += 1;
    const modelLabel = selectedModel.label;
    setUsedTokens((current) => Math.min(current + 420, 128_000));
    setMessages((current) => [
      ...current,
      {
        content,
        id: `local-user-${sequence}`,
        role: "user",
      },
      {
        content: thinkMode
          ? `Using ${modelLabel}, a useful next step is to name the owner, the deadline, and the risk for each item, then share a one-page summary with the team.`
          : `Using ${modelLabel}: name the owner, deadline, and risk for each item, then share a one-page summary.`,
        id: `local-assistant-${sequence}`,
        reasoning: thinkMode
          ? {
              content:
                "The user wants an actionable reply. Keep the answer short, name owners and risks, and avoid inventing backend work.",
              duration: 4,
            }
          : undefined,
        role: "assistant",
      },
    ]);
  };

  const showQueue =
    activeView === "chat" && messages.length > 0 && queueItems.length > 0;

  return (
    <SidebarProvider className="h-svh min-h-0">
      <ChatSidebar
        activeConversationId={activeConversationId}
        activeView={activeView}
        conversations={conversations}
        onConversationSelect={(id) => {
          const conversation = getConversation(id);
          if (!conversation) {
            return;
          }
          setActiveConversationId(id);
          setMessages(conversation.messages);
        }}
        onNewChat={() => {
          setActiveConversationId(null);
          setMessages([]);
        }}
        onProjectsSelect={() => setActiveView("projects")}
        onViewChange={setActiveView}
      />
      <SidebarInset className="min-h-0 overflow-hidden">
        <div className="flex h-svh min-h-0 flex-col lg:p-1.5 lg:ps-0">
          <div className="relative flex min-h-0 flex-1 flex-col bg-background lg:rounded-3xl lg:border lg:py-4 lg:ps-5 lg:pe-4">
            <header className="flex shrink-0 items-center justify-between gap-3 px-4 pt-4 lg:px-0 lg:pt-0">
              <div className="flex min-w-0 items-center gap-2">
                <SidebarTrigger className="lg:hidden" />
                <Breadcrumb>
                  <BreadcrumbList>
                    <BreadcrumbItem>
                      <BreadcrumbPage className="font-normal text-muted-foreground">
                        {breadcrumbProject}
                      </BreadcrumbPage>
                    </BreadcrumbItem>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                      <BreadcrumbPage>{breadcrumbTitle}</BreadcrumbPage>
                    </BreadcrumbItem>
                  </BreadcrumbList>
                </Breadcrumb>
              </div>
              <div className="flex items-center gap-1">
                <Context
                  costLabel="$0.042"
                  maxTokens={128_000}
                  usedTokens={usedTokens}
                >
                  <ContextTrigger />
                  <ContextContent>
                    <ContextHeader>
                      <ContextMeter />
                    </ContextHeader>
                    <ContextBody>
                      {CONTEXT_USAGE.map((usage) => (
                        <ContextUsageRow key={usage.title} {...usage} />
                      ))}
                    </ContextBody>
                    <ContextFooter />
                  </ContextContent>
                </Context>
                <Button
                  aria-label="Conversation options"
                  size="icon-xs"
                  variant="ghost"
                >
                  <EllipsisIcon aria-hidden />
                </Button>
              </div>
            </header>

            <div className="flex min-h-0 flex-1 flex-col">
              {activeView === "projects" ? (
                <ChatProjects />
              ) : (
                <ChatThread
                  messages={messages}
                  onSuggestion={handleSend}
                  userName="James"
                />
              )}
            </div>

            {showQueue ? (
              <div className="shrink-0 px-3 py-2 sm:px-4">
                <Queue className="mx-auto w-full max-w-3xl">
                  <QueueSection>
                    <QueueSectionHeader
                      title={`${queueItems.length} Queued Messages`}
                    />
                    <QueueSectionContent>
                      <QueueList>
                        {queueItems.map((item) => (
                          <QueueItem key={item.id}>
                            <QueueItemContent>{item.title}</QueueItemContent>
                            <QueueItemActions>
                              <QueueItemAction
                                aria-label={`Remove ${item.title}`}
                                onClick={() => {
                                  setQueueItems((current) =>
                                    current.filter(
                                      (queueItem) => queueItem.id !== item.id
                                    )
                                  );
                                }}
                              >
                                <Trash2Icon aria-hidden />
                              </QueueItemAction>
                            </QueueItemActions>
                          </QueueItem>
                        ))}
                      </QueueList>
                    </QueueSectionContent>
                  </QueueSection>
                </Queue>
              </div>
            ) : null}

            {activeView === "chat" ? (
              <div className="shrink-0 px-3 pt-2 pb-4 sm:px-4">
                <ChatComposer
                  model={model}
                  modelOptions={MODEL_OPTIONS}
                  onModelChange={setModel}
                  onSend={handleSend}
                  onThinkModeChange={setThinkMode}
                  thinkMode={thinkMode}
                />
              </div>
            ) : null}
          </div>
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
};

"use client";

import { useFilter, useListCollection } from "@ark-ui/react";
import { Combobox as ArkCombobox } from "@ark-ui/react/combobox";
import {
  BrainIcon,
  CrownIcon,
  MicIcon,
  PaperclipIcon,
  SearchIcon,
} from "lucide-react";
import React from "react";
import {
  Announcement,
  AnnouncementTitle,
} from "@/components/ui/announcement";
import { Button } from "@/components/ui/button";
import {
  Combobox,
  ComboboxButtonTrigger,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxGroup,
  ComboboxGroupLabel,
  ComboboxItem,
  ComboboxList,
  useComboboxContext,
} from "@/components/ui/combobox";
import {
  FileUpload,
  FileUploadTrigger,
} from "@/components/ui/file-upload";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group";
import {
  PromptInput,
  PromptInputButton,
  PromptInputFooter,
  type PromptInputStatus,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputTools,
} from "@/components/ui/prompt-input";
import { Toggle } from "@/components/ui/toggle";

interface ModelOption {
  group: string;
  label: string;
  value: string;
}

interface ChatComposerProps {
  model: string[];
  modelOptions: readonly ModelOption[];
  onModelChange: (value: string[]) => void;
  onSend: (content: string) => void;
  onThinkModeChange: (enabled: boolean) => void;
  thinkMode: boolean;
}

export const ChatComposer = ({
  model,
  modelOptions,
  onModelChange,
  onSend,
  onThinkModeChange,
  thinkMode,
}: ChatComposerProps) => {
  const [draft, setDraft] = React.useState("");
  const [status, setStatus] = React.useState<PromptInputStatus>("ready");

  const { contains } = useFilter({ sensitivity: "base" });
  const { collection, filter } = useListCollection({
    filter: contains,
    groupBy: (item) => item.group,
    groupSort: ["Models", "Agents"],
    initialItems: [...modelOptions],
  });

  return (
    <div className="mx-auto flex w-full max-w-3xl flex-col items-center gap-3">
      <div className="w-full rounded-2xl bg-muted/48 p-0.5">
        <Announcement className="w-full rounded-t-[15px] border-0 bg-transparent px-3 py-2 shadow-none">
          <CrownIcon aria-hidden className="text-muted-foreground" />
          <AnnouncementTitle className="text-muted-foreground text-xs">
            Access premium models & features
          </AnnouncementTitle>
          <span aria-hidden className="text-muted-foreground/64 text-xs">
            ·
          </span>
          <Button className="h-auto px-0 text-xs" variant="link">
            Upgrade
          </Button>
        </Announcement>

        <FileUpload accept="image/*,.pdf,.txt" className="gap-0" maxFiles={4}>
          <PromptInput
            className="rounded-[15px] border-0 bg-card shadow-xs/4"
            onStop={() => setStatus("ready")}
            onSubmit={({ text }) => {
              onSend(text);
              setDraft("");
              setStatus("streaming");
              window.setTimeout(() => setStatus("ready"), 900);
            }}
            status={status}
          >
            <PromptInputTextarea
              aria-label="Message"
              maxLength={2000}
              onChange={(event) => setDraft(event.target.value)}
              placeholder="How can I help you today?"
              rows={3}
              value={draft}
            />
            <PromptInputFooter>
              <PromptInputTools>
                <FileUploadTrigger asChild>
                  <PromptInputButton aria-label="Attach file" size="icon-xs">
                    <PaperclipIcon aria-hidden />
                  </PromptInputButton>
                </FileUploadTrigger>
                <Combobox
                  collection={collection}
                  inputBehavior="autohighlight"
                  onInputValueChange={({ inputValue }) => filter(inputValue)}
                  onValueChange={({ value }) => onModelChange(value)}
                  positioning={{ placement: "top" }}
                  selectionBehavior="clear"
                  value={model}
                >
                  <ComboboxButtonTrigger
                    placeholder="Model"
                    showTrigger={false}
                    size="xs"
                    variant="ghost"
                  />
                  <ComboboxContent className="max-h-72 w-52">
                    <ComboboxSearch />
                    <ComboboxList>
                      <ComboboxEmpty>No models found.</ComboboxEmpty>
                      {collection.group().map(([group, items]) => (
                        <ComboboxGroup key={group}>
                          <ComboboxGroupLabel>{group}</ComboboxGroupLabel>
                          {items.map((item) => (
                            <ComboboxItem item={item} key={item.value}>
                              {item.label}
                            </ComboboxItem>
                          ))}
                        </ComboboxGroup>
                      ))}
                    </ComboboxList>
                  </ComboboxContent>
                </Combobox>
                <Toggle
                  asChild
                  onPressedChange={onThinkModeChange}
                  pressed={thinkMode}
                  size="sm"
                >
                  <PromptInputButton
                    aria-label="Think mode"
                    className="data-[state=on]:bg-accent data-[state=on]:text-accent-foreground"
                    size="xs"
                  >
                    <BrainIcon aria-hidden />
                    Think
                  </PromptInputButton>
                </Toggle>
                <PromptInputButton aria-label="Voice input" size="icon-xs">
                  <MicIcon aria-hidden />
                </PromptInputButton>
              </PromptInputTools>
              <PromptInputSubmit />
            </PromptInputFooter>
          </PromptInput>
        </FileUpload>
      </div>

      <p className="text-center text-muted-foreground text-xs">
        AI can make{" "}
        <span className="font-medium text-foreground">mistakes</span>. Please
        double-check.
      </p>
    </div>
  );
};

const ComboboxSearch = () => {
  const { setInputValue } = useComboboxContext();

  return (
    <InputGroup className="mb-2 rounded-xl bg-input/32" size="md">
      <ArkCombobox.Input asChild>
        <InputGroupInput
          aria-label="Search models"
          onBlur={(event) => {
            const { currentTarget, relatedTarget } = event;
            const contentId = currentTarget.getAttribute("aria-controls");
            const content = contentId
              ? currentTarget.ownerDocument.getElementById(contentId)
              : null;
            const isInsideContent =
              relatedTarget instanceof Node && content?.contains(relatedTarget);

            if (!isInsideContent) {
              setInputValue("");
            }
          }}
          placeholder="Search models"
        />
      </ArkCombobox.Input>
      <InputGroupAddon>
        <SearchIcon aria-hidden className="opacity-64" />
      </InputGroupAddon>
    </InputGroup>
  );
};

"use client";

